#!/usr/bin/env bash
set -euo pipefail

# Drift check for generated agent slash-command prompts. .claude/commands/ is
# the single source of truth; the Copilot / Cursor / OpenCode / Codex variants
# are generated by scripts/sync-agent-prompts.mjs and must be regenerated
# (make sync-agent-prompts) whenever a canonical command changes.
echo "Checking agent slash-command prompt sync..."
node scripts/sync-agent-prompts.mjs --check
echo "Agent prompt sync check passed"
